     1	package com.loja.strategy;
     2	
     3	import com.loja.repository.OrderRepository;
     4	
     5	public class CouponFactory {
     6	    private final OrderRepository orderRepo;
     7	
     8	    public CouponFactory(OrderRepository orderRepo) {
     9	        this.orderRepo = orderRepo;
    10	    }
    11	
    12	    public CouponStrategy create(String couponCode) {
    13	        if (couponCode == null || couponCode.isEmpty()) {
    14	            return null;
    15	        }
    16	
    17	        return switch (couponCode) {
    18	            case "WELCOME10" -> new Welcome10Coupon(orderRepo);
    19	            case "MINUS50" -> new Minus50Coupon();
    20	            case "FREESHIPPING" -> new FreeShippingCoupon();
    21	            case "BUY3PAY2" -> new Buy3Pay2Coupon();
    22	            default -> null;
    23	        };
    24	    }
    25	
    26	    public boolean isValidCoupon(String couponCode) {
    27	        return couponCode != null && switch (couponCode) {
    28	            case "WELCOME10", "MINUS50", "FREESHIPPING", "BUY3PAY2" -> true;
    29	            default -> false;
    30	        };
    31	    }
    32	}
